<?php
namespace App\Services;
use App\Models\{Order,User};
use Illuminate\Support\Facades\{Cache,DB};
class OrderProtection {
 public static function phone($value){if(!is_string($value)&&!is_numeric($value))return null;$p=preg_replace('/\D/','',(string)$value);if(strpos($p,'880')===0)$p=substr($p,2);return preg_match('/^01[3-9][0-9]{8}$/D',$p)?$p:null;}
 public static function capture($order,$request){if(StoreOperations::get('order_origin_'.$order->id))return;$ip=$request->ip();if(!filter_var($ip,FILTER_VALIDATE_IP))return;StoreOperations::put('order_origin_'.$order->id,['ip'=>$ip,'at'=>now()->toIso8601String()]);}
 public static function info($order,$context=null){$origin=$context!==null?($context['origins'][$order->id]??[]):StoreOperations::get('order_origin_'.$order->id);$address=json_decode($order->shipping_address,true)?:[];$phone=self::phone($address['phone']??'');$user=$order->user_id?($order->relationLoaded('user')?$order->getRelation('user'):User::find($order->user_id)):null;$canBlock=!$user||$user->user_type==='customer';$ips=$context['ips']??StoreOperations::get('blocked_ips');$phones=$context['phones']??StoreOperations::get('blocked_phones');return ['ip'=>$origin['ip']??null,'recorded_at'=>$origin['at']??null,'ip_blocked'=>!empty($origin['ip'])&&in_array($origin['ip'],$ips,true),'user_id'=>($user ? $user->id : null),'customer_name'=>(($user ? $user->name : null) ?: ($address['name']??'Guest')),'guest'=>!$user,'can_block_customer'=>$canBlock&&($phone||$user),'customer_blocked'=>($canBlock&&$user&&$user->banned)||($phone&&in_array($phone,$phones,true)),'phone_blocked'=>$phone&&in_array($phone,$phones,true),'phone'=>$phone];}
 public static function forOrders($orders){$origins=[];$keys=[];foreach($orders as $order)$keys[]='ops_order_origin_'.$order->id;foreach(\App\Models\BusinessSetting::whereIn('type',$keys)->get()as $row){$id=(int)substr($row->type,17);$origins[$id]=json_decode(\Illuminate\Support\Facades\Crypt::decryptString($row->value),true)?:[];}$context=['origins'=>$origins,'ips'=>StoreOperations::get('blocked_ips'),'phones'=>StoreOperations::get('blocked_phones')];$out=[];foreach($orders as $order)$out[$order->id]=self::info($order,$context);return $out;}
 public static function toggle($order,$action,$request){return DB::transaction(function()use($order,$action,$request){$info=self::info($order);if(in_array($action,['block_ip','unblock_ip'],true)){abort_unless($info['ip'],422,'No IP recorded for this old order.');abort_if($action==='block_ip'&&$info['ip']===$request->ip(),422,'This is your current IP. Blocking it could block other customers on the same network.');$list=StoreOperations::get('blocked_ips');$list=array_values(array_diff($list,[$info['ip']]));if($action==='block_ip')$list[]=$info['ip'];StoreOperations::put('blocked_ips',$list);}elseif(in_array($action,['block_phone','unblock_phone'],true)){abort_unless($info['phone']&&$info['can_block_customer'],422,'Valid customer phone required; admin/staff orders are protected.');$list=StoreOperations::get('blocked_phones');$list=array_values(array_diff($list,[$info['phone']]));if($action==='block_phone')$list[]=$info['phone'];StoreOperations::put('blocked_phones',$list);}else{abort_unless(in_array($action,['block_customer','unblock_customer'],true)&&$info['can_block_customer'],422,'Admin/staff accounts cannot be blocked from an order.');$block=$action==='block_customer';if($info['user_id']){$user=User::whereKey($info['user_id'])->lockForUpdate()->firstOrFail();abort_unless($user->user_type==='customer',403);$user->banned=$block?1:0;$user->save();}if($info['phone']){$list=StoreOperations::get('blocked_phones');$list=array_values(array_diff($list,[$info['phone']]));if($block)$list[]=$info['phone'];StoreOperations::put('blocked_phones',$list);}}StoreOperations::audit($action,$order->id);return self::info($order);});}
 public static function assertAllowed($request,$phone=null){$user=$request->user();if(!$user&&$request->is('api/*'))$user=$request->user('sanctum');if($user&&$user->user_type==='customer')abort_if((bool)$user->banned,403,'This customer account is blocked. Contact store support.');$phone=self::phone($phone??$request->input('phone'));if($phone){$blocked=Cache::remember('ops_blocked_phones',60,fn()=>StoreOperations::get('blocked_phones'));abort_if(in_array($phone,$blocked,true),403,'Orders from this customer number are blocked. Contact store support.');}}
}
